function isPalindrome(x: number): boolean {
  // Отрицательные числа — не палиндромы (минус только слева).
  // Число, оканчивающееся на 0, — палиндром, только если это сам 0:
  // иначе первая цифра тоже должна быть 0, а ведущих нулей не бывает
  if (x < 0 || (x % 10 === 0 && x !== 0)) {
    return false;
  }

  // Разворачиваем только правую половину цифр
  let reversed = 0;
  while (x > reversed) {
    // Переносим последнюю цифру x в конец reversed
    reversed = reversed * 10 + (x % 10);
    x = Math.floor(x / 10);
  }

  // Чётное число цифр: половины равны (1221 → x = 12, reversed = 12).
  // Нечётное: средняя цифра оказалась в reversed, отбрасываем её
  // (12321 → x = 12, reversed = 123)
  return x === reversed || x === Math.floor(reversed / 10);
}

// Время: O(log10 x) — обрабатываем половину цифр
// Память: O(1)
